/// Runs one request.
pub fn transition(s: &Snapshot, req: &Request) -> Result<Reply, Error> {
    let user = req.user;
    match &req.op {
        Op::Messages { room, from, to, dir, limit, filter } => {
            api_message::get_message_events_route(s, user, *room, *from, *to, *dir, *limit, filter)
        }
        Op::Context { room, event, limit, filter } => {
            api_context::get_context_route(s, user, *room, *event, *limit, filter)
        }
        Op::Relations { room, event, rel_type, event_type, from, to, limit, recurse, dir } => {
            api_relations::paginate_relations_with_filter(
                s, user, *room, *event, *event_type, *rel_type, *from, *to, *limit, *recurse, *dir,
            )
        }
        Op::Threads { room, from, limit, participated } => {
            api_threads::get_threads_route(s, user, *room, *from, *limit, *participated)
        }
        Op::State { room } => api_state::get_state_events_route(s, user, *room),
        Op::StateEvent { room, kind, state_key } => {
            api_state::get_state_events_for_key_route(s, user, *room, *kind, *state_key)
        }
        Op::Members { room, at, membership, not_membership } => {
            api_members::get_member_events_route(s, user, *room, *at, *membership, *not_membership)
        }
        Op::JoinedMembers { room } => api_members::joined_members_route(s, user, *room),
        Op::InitialSync { room, limit } => api_room::room_initial_sync_route(s, user, *room, *limit),
        Op::RoomEvent { room, event } => api_room::get_room_event_route(s, user, *room, *event),
        Op::ServerCanSee { origin, room, event } => {
            Ok(Reply::CanSee(svc_accessor::server_can_see_event(s, *origin, *room, *event)))
        }
    }
}

/// `get_room_event_route`: one event, if visible and not ignored. The
/// release build does not check that the event is in `room`.
pub fn get_room_event_route(s: &Snapshot, user: u64, room: u64, event_id: u64) -> Result<Reply, Error> {
    let event = svc_timeline::get_pdu(s, event_id);
    let visible = svc_accessor::user_can_see_event(s, user, room, event_id);
    let p = match event {
        Ok(p) => p,
        Err(_) => return Err(Error::NotFound),
    };
    if !visible {
        return Err(Error::NotFound);
    }
    if api_message::is_ignored_pdu(s, &s.pdus[p], user) {
        return Err(Error::SenderIgnored);
    }
    Ok(Reply::RoomEvent { event: s.pdus[p].event_id })
}

/// `get_state_events_route`: the room's current state.
pub fn get_state_events_route(s: &Snapshot, user: u64, room: u64) -> Result<Reply, Error> {
    if !svc_accessor::user_can_see_state_events(s, user, room) {
        return Err(Error::Forbidden);
    }
    match svc_accessor::room_state_full_pdus(s, room) {
        Err(e) => Err(e),
        Ok(v) => {
            let mut events = Vec::new();
            let mut i = 0;
            while i < v.len() {
                events.push(s.pdus[v[i]].event_id);
                i += 1;
            }
            Ok(Reply::State { events })
        }
    }
}

/// `get_state_events_for_key_route`: one current state event.
pub fn get_state_events_for_key_route(s: &Snapshot, user: u64, room: u64, kind: Kind, state_key: u64) -> Result<Reply, Error> {
    if !svc_accessor::user_can_see_state_events(s, user, room) {
        return Err(Error::NotFound);
    }
    match svc_accessor::room_state_get(s, room, kind, state_key) {
        Err(_) => Err(Error::NotFound),
        Ok(p) => Ok(Reply::StateEvent { event: s.pdus[p].event_id }),
    }
}

/// `server_can_see_event`: for `invited` and `joined`, some current member
/// from `origin` must have had that membership at the event.
pub fn server_can_see_event(s: &Snapshot, origin: u64, room: u64, event_id: u64) -> bool {
    match pdu_shortstatehash(s, event_id) {
        Err(_) => true,
        Ok(hash) => {
            let hv = history_visibility_at(s, hash);
            let members = svc_cache::room_members(s, room);
            match hv {
                HistoryVisibility::Invited => any_member_was(s, hash, origin, &members, false),
                HistoryVisibility::Joined => any_member_was(s, hash, origin, &members, true),
                _ => true,
            }
        }
    }
}

